#!/usr/bin/env python3
# Generated by simit. Manual edits will be reported as ci=drift.
"""Revision admission for release-plz 0.3.172 and its Cargo publication guard."""

import email.utils
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import time
import urllib.parse


def git(*args):
    return subprocess.check_output(["git", *args], text=True).strip()


def api(path, key=None):
    pages = json.loads(
        subprocess.check_output(["gh", "api", "--paginate", "--slurp", path], text=True)
    )
    return [item for page in pages for item in (page[key] if key else page)]


def verify_receipt(pr):
    receipt = re.fullmatch(r"(.*)\n\n<!-- simit-release-plz-head: ([0-9a-f]{40}) ([0-9a-f]{64}) -->",
                           pr["body"] or "", flags=re.DOTALL)
    if (not receipt or receipt[2] != pr["head"]["sha"]
        or hashlib.sha256(receipt[1].encode("utf-8")).hexdigest() != receipt[3]):
        raise RuntimeError("release PR contains unrecognized/manual changes; reconcile it before updating")


def verify_release_head(sha):
    if subprocess.run(["git", "cat-file", "-e", f"{sha}^{{commit}}"],
                      stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:
        # Squashed/rebased PR heads need not be reachable from the event. Fetch
        # the immutable object with the read-only token, including private repos.
        subprocess.run(["git", "-c", "credential.helper=", "-c",
                        "credential.https://github.com.helper=!gh auth git-credential",
                        "fetch", "--no-tags", f"https://github.com/{os.environ['GITHUB_REPOSITORY']}.git", sha], check=True)
    public_key = committed_trust_root(os.environ["RELEASE_TRUST_ROOT"])
    with tempfile.TemporaryDirectory() as home:
        env = {**os.environ, "GNUPGHOME": home, "GIT_CONFIG_GLOBAL": os.devnull,
               "GIT_CONFIG_NOSYSTEM": "1"}
        subprocess.run(["gpg", "--batch", "--import"], input=public_key, env=env, check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        subprocess.run(["git", "-c", "gpg.format=openpgp", "-c", "gpg.program=gpg",
                        "verify-commit", sha], env=env, check=True)


def release_sha(event_sha, prs, commits):
    # Mirror should_release at release-plz commit 8b523fa6c4eb4992f18365ac50a196b4dc6a1013.
    # A merge releases the last PR commit; a squash releases the event commit.
    pr = next((pr for pr in prs if pr["head"]["ref"].startswith("release-plz-")), None)
    if pr is None:
        return ""
    if (
        not pr["merged_at"]
        or pr["base"]["repo"]["full_name"] != os.environ["GITHUB_REPOSITORY"]
        or pr["base"]["ref"] != os.environ["GITHUB_REF_NAME"]
        or (pr["head"].get("repo") or {}).get("full_name") != os.environ["GITHUB_REPOSITORY"]
        or not re.fullmatch(r"release-plz-[0-9a-f]{40}", pr["head"]["ref"])
    ):
        raise RuntimeError("release PR must be generated in this repository and merged into its default branch")
    verify_receipt(pr)
    history = commits(pr["number"])
    if not history:
        raise RuntimeError("release PR has no commits")
    sha = history[-1]["sha"]
    if not re.fullmatch(r"[0-9a-f]{40}", sha) or sha != pr["head"]["sha"]:
        raise RuntimeError("invalid release commit")
    verify_release_head(sha)
    ancestor = subprocess.run(
        ["git", "merge-base", "--is-ancestor", sha, event_sha],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    return sha if ancestor.returncode == 0 else event_sha


def prior_run():
    repo = os.environ["GITHUB_REPOSITORY"]
    run_id = int(os.environ["GITHUB_RUN_ID"])
    current = github("GET", f"repos/{repo}/actions/runs/{run_id}", {})
    branch = urllib.parse.quote(os.environ["GITHUB_REF_NAME"], safe="")
    runs = api(f"repos/{repo}/actions/workflows/{int(current['workflow_id'])}/runs?event=push&branch={branch}&per_page=100", "workflow_runs")
    if current["id"] != run_id or not any(run["id"] == run_id for run in runs):
        raise RuntimeError("release-plz workflow-run history is incomplete")
    previous = max((run for run in runs if run["run_number"] < current["run_number"]),
                   key=lambda run: run["run_number"], default=None)
    # Filtered Actions queries expose at most 1,000 results. Never mistake a
    # truncated historical run for initial enrollment when many newer runs exist.
    if previous is None and len(runs) >= 1000:
        raise RuntimeError("release-plz predecessor is outside the provider history window")
    if previous and previous["status"] != "completed":
        jobs = api(f"repos/{repo}/actions/runs/{int(previous['id'])}/jobs?filter=latest&per_page=100", "jobs")
        if not any(job["name"] == "select" and job["status"] == "completed"
                   and job["conclusion"] == "success" for job in jobs):
            # The queued select job owns the admission slot. Waiting for a
            # predecessor that still needs that slot would deadlock the queue.
            raise RuntimeError(f"release-plz predecessor run {previous['id']} has not completed admission; retry in run order")
    deadline = time.monotonic() + 350 * 60
    while previous:
        if previous["status"] == "completed":
            if previous["conclusion"] != "success":
                raise RuntimeError(f"release-plz predecessor run {previous['id']} must succeed; retry/reconcile it before advancing")
            break
        if time.monotonic() >= deadline:
            raise RuntimeError(f"release-plz predecessor run {previous['id']} did not complete within the wait budget")
        time.sleep(15)
        previous = github("GET", f"repos/{repo}/actions/runs/{previous['id']}", {})


def select():
    event_sha = os.environ["GITHUB_SHA"]
    if (
        not re.fullmatch(r"[0-9a-f]{40}", event_sha)
        or git("rev-parse", "HEAD") != event_sha
    ):
        raise RuntimeError("selection requires the immutable event checkout")
    event = json.loads(Path(os.environ["GITHUB_EVENT_PATH"]).read_text())
    before = event.get("before", "")
    if (os.environ["GITHUB_EVENT_NAME"] != "push" or event.get("after") != event_sha
        or not re.fullmatch(r"[0-9a-f]{40}", before)):
        raise RuntimeError("release selection requires the complete native push range")
    if before != "0" * 40 and subprocess.run(
        ["git", "merge-base", "--is-ancestor", before, event_sha],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    ).returncode:
        raise RuntimeError("release selection requires complete fast-forward push history; reconcile it before advancing")
    repo = os.environ["GITHUB_REPOSITORY"]
    revisions = git("rev-list", "--reverse", f"{before}..{event_sha}" if before != "0" * 40 else event_sha).splitlines()
    releases = {}
    for revision in revisions:
        for pr in api(f"repos/{repo}/commits/{revision}/pulls?per_page=100"):
            # Associations also include PR branch commits and old/open PRs.
            # Only an actual merge introduced by this push can trigger release.
            if pr["head"]["ref"].startswith("release-plz-") and pr.get("merge_commit_sha") == revision:
                releases[pr["number"]] = (revision, pr)
    if len(releases) > 1:
        raise RuntimeError("multiple release PRs in one push require reconciliation before advancing")
    merge, prs = next(((revision, [pr]) for revision, pr in releases.values()), (event_sha, []))
    sha = release_sha(
        merge, prs,
        lambda number: api(f"repos/{repo}/pulls/{number}/commits?per_page=100"),
    )
    expected = os.environ.get("SIMIT_EXPECTED_RELEASE_SHA")
    if expected is not None and sha != expected:
        raise RuntimeError("release-plz revision changed after qualification")
    with open(os.environ["GITHUB_OUTPUT"], "a", encoding="utf-8") as output:
        output.write(f"release_sha={sha}\n")


def cargo():
    args = sys.argv[2:]
    if (not args or args[0] not in ("metadata", "info", "publish")
        or any(arg == "--config" or arg.startswith("--config=") for arg in args)):
        raise RuntimeError("credentialed release-plz only permits data-only Cargo operations")
    if args[0] == "publish":
        expected = os.environ["SIMIT_EXPECTED_RELEASE_SHA"]
        if not expected or git("rev-parse", "HEAD") != expected:
            raise RuntimeError("refusing cargo publish from an unqualified revision")
        package = args[args.index("--package") + 1]
        env = {**os.environ, "PATH": os.environ["SIMIT_RELEASE_PLZ_TOOL_PATH"]}
        env["CRATES_IO_API_TOKEN"] = env.get("CARGO_REGISTRY_TOKEN", "")
        subprocess.run([
            os.environ["SIMIT_RELEASE_PLZ_PUBLISHER"], "release", "publisher",
            "--publisher-stage", "prepare" if "--dry-run" in args else "publish",
            "--repo", os.environ["GITHUB_REPOSITORY"], "--package", package,
            "--release-plz-archives", f"{os.environ['RUNNER_TEMP']}/release-plz-archives",
        ], check=True, env=env)
        # The pinned release-plz parses Cargo's stderr to recognize a successful
        # upload (including dry runs); return that protocol only after admission.
        print(f"   Uploading {package}", file=sys.stderr)
        return
    real_cargo = os.environ["SIMIT_REAL_CARGO"]
    # Cargo discovers config from cwd, not --manifest-path. Never execute project
    # wrappers/credential providers, and never pass release credentials to Cargo.
    with tempfile.TemporaryDirectory() as home:
        env = {
            "PATH": os.environ["SIMIT_RELEASE_PLZ_TOOL_PATH"], "HOME": home,
            "CARGO_HOME": home, "RUSTUP_TOOLCHAIN": "stable",
            "RUSTUP_HOME": os.environ.get("RUSTUP_HOME", str(Path.home() / ".rustup")),
        }
        raise SystemExit(subprocess.run([real_cargo, *args], cwd="/", env=env).returncode)


def git_credentials():
    root = os.environ["RUNNER_TEMP"]
    # release-plz's temporary clones do not inherit checkout-local config.
    count = int(os.environ.get("GIT_CONFIG_COUNT", "0"))
    for key, value in (
        ("credential.helper", ""),
        ("credential.https://github.com.helper", f"{root}/release-plz-credentials"),
        ("credential.https://github.com.useHttpPath", "true"),
        ("core.symlinks", "false"),
    ):
        os.environ[f"GIT_CONFIG_KEY_{count}"] = key
        os.environ[f"GIT_CONFIG_VALUE_{count}"] = value
        count += 1
    os.environ["GIT_CONFIG_COUNT"] = str(count)


def run():
    root = os.environ["RUNNER_TEMP"]
    git_credentials()
    real_cargo = shutil.which("cargo")
    if real_cargo is None:
        raise RuntimeError("cargo is required in the selected release runtime")
    os.environ["SIMIT_REAL_CARGO"] = real_cargo
    os.environ["SIMIT_RELEASE_PLZ_TOOL_PATH"] = os.environ["PATH"]
    os.environ["SIMIT_RELEASE_PLZ_SOURCE"] = f"{root}/release-plz-event-source"
    # The CLI's native Cargo library also reads workspace config. Keep it in a
    # clean sparse checkout: Git checkout must not restore credential providers
    # or executable wrappers while release-plz switches release revisions.
    settings = {key: git("config", "--get", key) for key in (
        "user.name", "user.email", "user.signingkey", "gpg.program", "tag.gpgSign",
    )}
    source = os.environ["SIMIT_RELEASE_PLZ_SOURCE"]
    expected = os.environ["SIMIT_EXPECTED_RELEASE_SHA"]
    if not re.fullmatch(r"[0-9a-f]{40}", expected):
        raise RuntimeError("publication requires an admitted release revision")
    publish = f"{root}/release-plz-publish"
    subprocess.run(["git", "clone", "--no-hardlinks", "--no-checkout", "--", source, publish], check=True)
    os.chdir(publish)
    subprocess.run(["git", "config", "core.symlinks", "false"], check=True)
    subprocess.run(["git", "sparse-checkout", "set", "--no-cone", "--stdin"],
        input="/*\n!.cargo/\n!**/.cargo/\n", text=True, check=True)
    subprocess.run(["git", "checkout", "--detach", expected], check=True)
    for key, value in settings.items():
        subprocess.run(["git", "config", "--local", key, value], check=True)
    subprocess.run(["git", "remote", "set-url", "origin",
                    f"https://github.com/{os.environ['GITHUB_REPOSITORY']}.git"], check=True)
    os.environ["RUSTUP_HOME"] = os.environ.get("RUSTUP_HOME", str(Path.home() / ".rustup"))
    os.environ["HOME"] = f"{root}/release-plz-home"
    os.environ["CARGO_HOME"] = f"{root}/release-plz-home/cargo"
    os.environ["RUSTUP_TOOLCHAIN"] = "stable"
    os.environ["GIT_CONFIG_NOSYSTEM"] = "1"
    os.environ["GIT_CONFIG_GLOBAL"] = os.devnull
    Path(os.environ["CARGO_HOME"]).mkdir(parents=True)
    os.environ["PATH"] = f"{root}/release-plz-guard:{os.environ['PATH']}"
    os.environ["CARGO"] = f"{root}/release-plz-guard/cargo"
    release_plz = f"{root}/release-plz/bin/release-plz"
    os.execv(release_plz, [release_plz, *sys.argv[2:]])


def update():
    git_credentials()
    release_plz = f"{os.environ['RUNNER_TEMP']}/release-plz/bin/release-plz"
    os.execv(release_plz, [release_plz, "update", *sys.argv[2:]])


def prepare_pr():
    directory = Path(os.environ["RUNNER_TEMP"]) / "release-plz-pr"
    directory.mkdir()
    for path in filter(None, git("ls-files", "--others", "--exclude-standard", "-z").split("\0")):
        if Path(path).name in ("Cargo.toml", "Cargo.lock", "CHANGELOG.md"):
            subprocess.run(["git", "add", "--intent-to-add", "--", path], check=True)
    # Only data crosses to the credentialed worker; its index admission below
    # independently checks paths and modes before the signing key is imported.
    patch = subprocess.check_output(["git", "diff", "--binary", "HEAD"])
    (directory / "update.patch").write_bytes(patch)
    summary = Path(os.environ["RUNNER_TEMP"]) / "release-plz-update.log"
    (directory / "summary.txt").write_bytes(summary.read_bytes()[:60_000])


def read_data(path, limit):
    if not stat.S_ISREG(path.lstat().st_mode) or path.stat().st_size > limit:
        raise RuntimeError("invalid release-plz data artifact")
    return path.read_bytes()


def admit_pr():
    if git("rev-parse", "HEAD") != os.environ["GITHUB_SHA"]:
        raise RuntimeError("release PR admission requires the event checkout")
    directory = Path(os.environ["RUNNER_TEMP"]) / "release-plz-pr"
    patch = read_data(directory / "update.patch", 16 * 1024 * 1024)
    if patch:
        subprocess.run(["git", "apply", "--cached", "--binary", "-"], input=patch, check=True)
    # Disabling rename detection exposes both paths, including the removed
    # source. No destination can hide a workflow deletion behind an allowed name.
    paths = git("diff", "--cached", "--no-renames", "--name-only", "-z").split("\0")
    for path in filter(None, paths):
        parts = Path(path).parts
        if (not parts or Path(path).is_absolute()
            or any(part in (".", "..", ".git", ".github", ".forgejo", ".simit") for part in parts)
            or parts[-1] not in ("Cargo.toml", "Cargo.lock", "CHANGELOG.md")):
            raise RuntimeError("release-plz update changed a non-release path")
        records = git("--literal-pathspecs", "ls-files", "--stage", "-z", "--", path)
        if not records.startswith(("100644 ", "100755 ")) or records.count("\0") > 1:
            raise RuntimeError("release-plz update contains a link or deletion")
    tree = git("write-tree")
    if tree == git("rev-parse", "HEAD^{tree}"):
        tree = ""
    with open(os.environ["GITHUB_ENV"], "a", encoding="utf-8") as output:
        output.write(f"SIMIT_RELEASE_PR_TREE={tree}\n")


def github(method, path, payload):
    return json.loads(subprocess.check_output(
        ["gh", "api", "--method", method, path, "--input", "-"],
        input=json.dumps(payload), text=True,
    ))


def apply_pr():
    tree = os.environ.get("SIMIT_RELEASE_PR_TREE", "")
    if not tree:
        return
    if git("write-tree") != tree or git("rev-parse", "HEAD") != os.environ["GITHUB_SHA"]:
        raise RuntimeError("admitted release PR source changed")
    git_credentials()
    os.environ["GH_TOKEN"] = os.environ["GIT_TOKEN"]
    repo = os.environ["GITHUB_REPOSITORY"]
    base = os.environ["GITHUB_REF_NAME"]
    base_ref = urllib.parse.quote(base, safe="")
    current = json.loads(subprocess.check_output(["gh", "api", f"repos/{repo}/git/ref/heads/{base_ref}"], text=True))
    if current["object"]["sha"] != os.environ["GITHUB_SHA"]:
        print("Newer default-branch source supersedes this release PR update")
        return
    prs = [pr for pr in api(f"repos/{repo}/pulls?state=open&base={base_ref}&per_page=100")
           if pr["head"]["ref"].startswith("release-plz-") and (pr["head"].get("repo") or {}).get("full_name") == repo]
    if len(prs) > 1:
        raise RuntimeError("reconcile multiple open release-plz PRs before updating")
    previous = prs[0] if prs else None
    branch = previous["head"]["ref"] if previous else f"release-plz-{os.environ['GITHUB_SHA']}"
    if not re.fullmatch(r"release-plz-[0-9a-f]{40}", branch):
        raise RuntimeError("reconcile an unrecognized release-plz branch before updating")
    summary = read_data(Path(os.environ["RUNNER_TEMP"]) / "release-plz-pr/summary.txt", 60_000).decode("utf-8", errors="replace")
    content = f"Prepared by release-plz 0.3.172.\n\n```text\n{summary}\n```"
    digest = hashlib.sha256(content.encode("utf-8")).hexdigest()

    def message(previous_body, body_digest=digest):
        prior = hashlib.sha256(previous_body.encode("utf-8")).hexdigest()
        return f"chore: release\n\nPrepared by release-plz 0.3.172.\n\nsimit-release-plz-body: {body_digest}\nsimit-release-plz-previous-body: {prior}"

    reference = f"refs/heads/{branch}"
    remote = git("ls-remote", "--heads", "origin", reference).split()
    if remote and (len(remote) != 2 or remote[1] != reference or not re.fullmatch(r"[0-9a-f]{40}", remote[0])):
        raise RuntimeError("invalid release-plz remote reference")
    expected = remote[0] if remote else ""
    if previous and expected != previous["head"]["sha"]:
        raise RuntimeError("release PR branch changed during delivery; retry/reconcile it")
    prior_body = (previous["body"] or "") if previous else ""
    resume = False
    pending = False
    if expected:
        subprocess.run(["git", "fetch", "--no-tags", "origin", expected], check=True)
        verify_release_head(expected)
        head_tree, parents, head_message = git("show", "-s", "--format=%T%n%P%n%B", expected).split("\n", 2)
        same_source = head_tree == tree and parents == os.environ["GITHUB_SHA"]
        body = f"{content}\n\n<!-- simit-release-plz-head: {expected} {digest} -->"
        if previous and same_source and prior_body == body:
            print(f"https://github.com/{repo}/pull/{previous['number']}")
            return
        # The signed commit binds both the prepared summary and the exact old
        # PR body. A failed POST/PATCH can resume, but manual edits cannot.
        resume = same_source and head_message == message(prior_body)
        # A current-source successor may replace an abandoned older delivery,
        # but only its signed prior-body binding can waive the stale head receipt.
        recorded = re.search(r"\nsimit-release-plz-body: ([0-9a-f]{64})\n", head_message)
        pending = bool(recorded and head_message == message(prior_body, recorded[1]))
        pending = pending and bool(re.fullmatch(r"[0-9a-f]{40}", parents)) and subprocess.run(
            ["git", "merge-base", "--is-ancestor", parents, os.environ["GITHUB_SHA"]],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        ).returncode == 0
        if not previous and not resume:
            raise RuntimeError("reconcile an unrecognized release-plz branch before creating a PR")
    sha = expected
    if not resume:
        if previous and not pending:
            verify_receipt(previous)
        sha = subprocess.check_output(["git", "commit-tree", "-S", tree, "-p", os.environ["GITHUB_SHA"]],
            input=message(prior_body) + "\n", text=True).strip()
        subprocess.run(["git", "push", f"--force-with-lease={reference}:{expected}", "origin", f"{sha}:{reference}"], check=True)
    body = f"{content}\n\n<!-- simit-release-plz-head: {sha} {digest} -->"
    if previous:
        result = github("PATCH", f"repos/{repo}/pulls/{previous['number']}", {"body": body})
    else:
        result = github("POST", f"repos/{repo}/pulls", {"title": "chore: release", "head": branch, "base": base, "body": body})
    print(result["html_url"])


def committed_trust_root(trust_root):
    path = Path(trust_root)
    if path.is_absolute() or not path.parts or ".." in path.parts:
        raise RuntimeError("release trust root must be a committed relative path")
    records = subprocess.check_output(["git", "ls-tree", "-z", "HEAD", "--", trust_root], text=True)
    records = [record.split("\t", 1)[0].split() for record in records.split("\0")
               if record and record.split("\t", 1)[1] == path.as_posix()]
    if len(records) != 1 or records[0][0] not in ("100644", "100755") or records[0][1] != "blob":
        raise RuntimeError("release trust root must be a regular committed file")
    return subprocess.check_output(["git", "cat-file", "blob", records[0][2]])


def signing_identity(trust_root):
    def gpg(*args, input=None):
        return subprocess.check_output(
            ["gpg", "--batch", "--with-colons", *args], text=True, input=input
        )

    # Only primary fingerprints: a private subkey is authorized by its primary.
    def primaries(text):
        primary = False
        for line in text.splitlines():
            fields = line.split(":")
            if fields[0] in ("pub", "sec"):
                primary = True
            elif fields[0] == "fpr" and primary:
                yield fields[9]
                primary = False

    public_key = committed_trust_root(trust_root)
    authorized = set(primaries(subprocess.check_output(
        ["gpg", "--batch", "--with-colons", "--show-keys"], input=public_key,
    ).decode("utf-8")))
    key = next(
        (key for key in primaries(gpg("--list-secret-keys")) if key in authorized), None
    )
    if key is None:
        raise RuntimeError(
            "CI signing key is not authorized by the committed release trust root"
        )
    uid = next(
        line.split(":")[9]
        for line in gpg("--list-keys", key).splitlines()
        if line.startswith("uid:")
    )
    uid = re.sub(r"\\x([0-9a-fA-F]{2})", lambda match: chr(int(match[1], 16)), uid)
    # GPG UIDs are not RFC 5322 display names: an unquoted ':' in the name
    # must not be interpreted as a mail group and discard the preceding name.
    name, _, mailbox = uid.rpartition("<")
    name = name.strip()
    _, address = email.utils.parseaddr(f"<{mailbox}")
    if not name or not address or any(c in name + address for c in "\r\n"):
        raise RuntimeError("authorized signing key needs a name and email UID")
    for field, value in (
        ("user.name", name),
        ("user.email", address),
        ("user.signingkey", key),
    ):
        subprocess.run(["git", "config", "--local", field, value], check=True)


if __name__ == "__main__":
    if sys.argv[1] == "prior-run":
        prior_run()
    elif sys.argv[1] == "select":
        select()
    elif sys.argv[1] == "cargo":
        cargo()
    elif sys.argv[1] == "identity":
        signing_identity(sys.argv[2])
    elif sys.argv[1] == "run":
        run()
    elif sys.argv[1] == "prepare-pr":
        prepare_pr()
    elif sys.argv[1] == "update":
        update()
    elif sys.argv[1] == "admit-pr":
        admit_pr()
    elif sys.argv[1] == "apply-pr":
        apply_pr()
    else:
        raise SystemExit("unknown release-plz admission command")
